// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint256 ts) public {
        vm.assume(actor != address(0));
        ts = bound(ts, 1, 10**10);

        vm.deal(actor, 20 ether);

        vm.warp(ts);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback call failed unexpectedly");

        assertTrue(c.pastBlockTime() == uint256(block.timestamp) + 1);
    }
}
